package com.iminiapp.backend.vehicle.application;
import com.iminiapp.backend.identity.web.AuthenticatedPrincipal;
import com.iminiapp.backend.shared.error.*;
import com.iminiapp.backend.vehicle.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;
import java.util.*;
@Service public class VehicleAdminManagementService {
 private final JdbcTemplate jdbc; public VehicleAdminManagementService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional public VehicleResponse updateVehicle(AuthenticatedPrincipal p,long id,VehicleAdminUpdateRequest r){long op=user(p);if(r==null)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"请求体不能为空");String s=r.status()==null?null:r.status().trim().toUpperCase(Locale.ROOT);if(s!=null&&!Set.of("AVAILABLE","DISPATCHED","MAINTENANCE","INACTIVE").contains(s))throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"车辆状态不正确");if(r.imageUrl()!=null&&r.imageUrl().length()>512)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"imageUrl 最长512字符");if(r.configuration()!=null&&!r.configuration().isBlank()){Integer valid=jdbc.queryForObject("SELECT JSON_VALID(?)",Integer.class,r.configuration());if(valid==null||valid!=1)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"configuration 必须是合法JSON");}int n=jdbc.update("UPDATE bf_vehicle SET image_url=COALESCE(?,image_url),configuration=CASE WHEN ? IS NULL OR ?='' THEN configuration ELSE CAST(? AS JSON) END,status=COALESCE(?,status) WHERE id=?",r.imageUrl(),r.configuration(),r.configuration(),r.configuration(),s,id);if(n!=1)throw new BusinessException(CommonErrorCode.NOT_FOUND,"车辆不存在");jdbc.update("INSERT INTO bf_audit_log(operator_id,action,target_type,target_id,detail) VALUES (?,'VEHICLE_UPDATE','VEHICLE',?,JSON_OBJECT('status',?))",op,String.valueOf(id),s);return find(id);}
 @Transactional public void updateTariff(AuthenticatedPrincipal p,long modelId,VehicleTariffUpdateRequest r){long op=user(p);if(r==null||r.halfDayCent()==null||r.fullDayCent()==null)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"halfDayCent 和 fullDayCent 不能为空");for(Long value:Arrays.asList(r.halfDayCent(),r.fullDayCent(),r.monthCent(),r.bareMonthCent(),r.overtimeCentPerHour(),r.overDistanceCentPerKm()))if(value!=null&&value<0)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,"价格不能为负数");List<Map<String,Object>> models=jdbc.queryForList("SELECT id,model_code,name FROM bf_vehicle_model WHERE id=?",modelId);if(models.isEmpty())throw new BusinessException(CommonErrorCode.NOT_FOUND,"车型不存在");List<Long> tariffIds=jdbc.queryForList("SELECT id FROM bf_vehicle_tariff WHERE model_id=? AND enabled=1 ORDER BY effective_from DESC,id DESC LIMIT 1",Long.class,modelId);if(tariffIds.isEmpty()){jdbc.update("INSERT INTO bf_vehicle_tariff(model_id,half_day_cent,full_day_cent,month_cent,bare_month_cent,overtime_cent_per_hour,over_distance_cent_per_km,half_day_limit_hours,half_day_limit_km,full_day_limit_hours,full_day_limit_km,month_limit_km,effective_from,enabled) VALUES (?,?,?,?,?,?,?,4,150,8,300,4000,CURRENT_DATE,?)",modelId,r.halfDayCent(),r.fullDayCent(),r.monthCent(),r.bareMonthCent(),r.overtimeCentPerHour(),r.overDistanceCentPerKm(),Boolean.FALSE.equals(r.enabled())?0:1);}else{jdbc.update("UPDATE bf_vehicle_tariff SET half_day_cent=?,full_day_cent=?,month_cent=?,bare_month_cent=?,overtime_cent_per_hour=?,over_distance_cent_per_km=?,enabled=COALESCE(?,enabled) WHERE id=?",r.halfDayCent(),r.fullDayCent(),r.monthCent(),r.bareMonthCent(),r.overtimeCentPerHour(),r.overDistanceCentPerKm(),r.enabled(),tariffIds.get(0));}ensureRentalSku(models.get(0));jdbc.update("INSERT INTO bf_audit_log(operator_id,action,target_type,target_id,detail) VALUES (?,'VEHICLE_TARIFF_UPDATE','VEHICLE_MODEL',?,JSON_OBJECT('halfDayCent',?,'fullDayCent',?))",op,String.valueOf(modelId),r.halfDayCent(),r.fullDayCent());}
 private void ensureRentalSku(Map<String,Object> model){String code=String.valueOf(model.get("model_code")),name=String.valueOf(model.get("name"));jdbc.update("INSERT INTO bf_resource(resource_type,name,description,status,attributes) SELECT 'VEHICLE_RENTAL',?,'社会租赁车型','ACTIVE',JSON_OBJECT('modelCode',?) WHERE NOT EXISTS(SELECT 1 FROM bf_resource WHERE resource_type='VEHICLE_RENTAL' AND name=?)","社会租赁-"+name,code,"社会租赁-"+name);Long resourceId=jdbc.queryForObject("SELECT id FROM bf_resource WHERE resource_type='VEHICLE_RENTAL' AND name=? ORDER BY id LIMIT 1",Long.class,"社会租赁-"+name);jdbc.update("INSERT INTO bf_resource_sku(resource_id,sku_code,name,price_cent,status,attributes) VALUES (?,?,?,?,'ACTIVE',JSON_OBJECT('modelId',?)) ON DUPLICATE KEY UPDATE name=VALUES(name),price_cent=VALUES(price_cent),status='ACTIVE'",resourceId,"VEHICLE_RENTAL_"+code,name+"社会租赁",jdbc.queryForObject("SELECT half_day_cent FROM bf_vehicle_tariff WHERE model_id=? ORDER BY effective_from DESC,id DESC LIMIT 1",Long.class,model.get("id")),model.get("id"));}
 private VehicleResponse find(long id){return jdbc.queryForObject("SELECT v.id,v.vehicle_no,v.plate_no,m.model_code,m.name,m.seat_count,v.status,v.mileage_km FROM bf_vehicle v JOIN bf_vehicle_model m ON m.id=v.model_id WHERE v.id=?",(rs,n)->new VehicleResponse(rs.getLong(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getInt(6),rs.getString(7),rs.getBigDecimal(8)),id);}
 private long user(AuthenticatedPrincipal p){jdbc.update("INSERT INTO bf_user(wechat_openid,nickname,status) VALUES (?,?,'ACTIVE') ON DUPLICATE KEY UPDATE nickname=VALUES(nickname)",p.databaseOpenId(),p.displayName());return jdbc.queryForObject("SELECT id FROM bf_user WHERE wechat_openid=?",Long.class,p.databaseOpenId());}
}
